const CPART=[];
{const per=Math.floor(N/NCEL), ex=N-per*NCEL;
 for(let c=0;c<NCEL;c++){
   const cnt=per+(c<ex?1:0);
   const mem=Math.round(cnt*.70);
   for(let j=0;j<cnt;j++){
     if(j<mem)CPART.push({c:c,k:0,a:j/mem*6.283,r:1});
     else{const jj=j-mem,nn=cnt-mem;
       CPART.push({c:c,k:1,a:jj*2.39996,r:.34*Math.sqrt((jj+.5)/nn)});}}}}
function cellTarget(i){
  const pt=CPART[i], c=CELLS[pt.c];
  const rt=T*.19,ca=Math.cos(rt),sa=Math.sin(rt);
  const X=c[0]*ca+c[2]*sa, Z=-c[0]*sa+c[2]*ca, Y=c[1];
  const k=1/(1-.28*Z), R=158, CRAD=78;
  const bob=1+.026*Math.sin(T*1.0+pt.c*1.9);
  const cx=X*R*k*bob, cy=Y*R*k*.96*bob;
  const cyc=8, who=Math.floor(T/cyc)%NCEL;
  const sp=(pt.c===who)?Math.pow(Math.max(0,Math.sin(((T%cyc)/cyc)*Math.PI)),1.4):0;
  const half=(pt.a%6.283<3.14159)?-1:1;
  const ang=sp>.01?((pt.a%6.283)-(half>0?3.14159:0))*2:pt.a;
  const rad=CRAD*k*(1-.24*sp);
  const wob=pt.k?1+.05*Math.sin(T*1.5+i):1;
  return [cx+Math.cos(ang)*rad*pt.r*wob+half*CRAD*k*.86*sp,
          cy+Math.sin(ang)*rad*pt.r*wob, Z];}

